//
//  SPDX-License-Identifier: GPL-3.0-or-later
//  Copyright (C) 2019-2022, respective authors of MCFM.
//
#include <fvf.hpp>
#include <cmath>
#include <complex>
#include <FArray.hpp>
#include <Need.hpp>
#include <W1jet.hpp>
#include <heldefs_mod.hpp>
#include <mxpart_mod.hpp>
#include <sprods_com_mod.hpp>

using namespace mxpart_mod;
using namespace sprods_com_mod;
using namespace heldefs_mod;

std::complex<double> Fvf(int st, int j1, int j2, int j3, int j4, int j5, int j6,
                          FArray2D<std::complex<double>>& za, FArray2D<std::complex<double>>& zb) {
  std::complex<double> Fvf_res;

  auto zab2 = [&za, &zb](int i1, int i2, int i3, int i4) {
    return za(i1, i2) * zb(i2, i4) + za(i1, i3) * zb(i3, i4);
  };

  std::complex<double> I3m123456 = i3m(s(j1, j2), s(j3, j4), s(j5, j6));
  std::complex<double> I3m563412 = I3m123456;

  if (st == hqpqbmgpgm) {
    Fvf_res =
      -std::pow(zab2(j5, j2, j4, j1), 2) / (za(j5, j6) * zb(j1, j2) * std::pow(zab2(j3, j1, j2, j4), 2))
      * Lsm1_2mh(s(j3, j4), t(j1, j2, j4), s(j1, j2), s(j5, j6))
      -std::pow(zab2(j2, j1, j3, j6), 2) / (za(j1, j2) * zb(j5, j6) * std::pow(zab2(j3, j1, j2, j4), 2))
      * Lsm1_2mh(s(j3, j4), t(j1, j2, j3), s(j1, j2), s(j5, j6))

      -I3m123456 * za(j4, j5) * zb(j1, j3)
      * zab2(j2, j1, j3, j6) / (2.0 * zab2(j3, j1, j2, j4) * t(j1, j2, j3))

      -I3m123456 * za(j2, j4) * zb(j3, j6)
      * zab2(j5, j2, j4, j1) / (2.0 * zab2(j3, j1, j2, j4) * t(j1, j2, j4))

      +I3m563412 * za(j2, j4) * zb(j3, j6)
      * zab2(j5, j3, j6, j1) / (2.0 * zab2(j3, j1, j2, j4) * t(j3, j5, j6))

      +I3m563412 * za(j4, j5) * zb(j1, j3)
      * zab2(j2, j4, j5, j6) / (2.0 * zab2(j3, j1, j2, j4) * t(j4, j5, j6));
  } else if (st == hqpqbmgpgp) {
    Fvf_res = -std::pow(za(j2, j5), 2) / (za(j1, j2) * za(j5, j6) * std::pow(za(j3, j4), 2))
      * Lsm1_2me(t(j1, j2, j3), t(j1, j2, j4), s(j1, j2), s(j5, j6));
  }

  Fvf_res = Fvf_res; // @coverage-probe
  return Fvf_res;
}

extern "C" {
  std::complex<double> Fvf_wrapper(int st, int j1, int j2, int j3, int j4, int j5, int j6,
                                    std::complex<double>* fza, std::complex<double>* fzb) {
    FArray2D<std::complex<double>> za(fza, mxpart, mxpart);
    FArray2D<std::complex<double>> zb(fzb, mxpart, mxpart);
    return Fvf(st, j1, j2, j3, j4, j5, j6, za, zb);
  }
}

#ifndef FARRAY_H
#define FARRAY_H

#include <cstddef>
#include <initializer_list>

template <typename T>
class FArray1D {

  private:
    bool ownsData;
    int start_i;

  public:
    size_t ni;
    T* data;

    // Constructor to allocate memory
    FArray1D(size_t ni, int start_i=1)
        : ni(ni), start_i(start_i), data(new T[ni]), ownsData(true) {}

    // Constructor to use existing Fortran array
    FArray1D(T* fortranArray, size_t ni, int start_i=1)
        : ni(ni), start_i(start_i), data(fortranArray), ownsData(false) {}

    // Constructor using an initializer list
    FArray1D(std::initializer_list<T> values, size_t ni, int start_i = 1)
        : ni(ni), start_i(start_i), data(new T[ni]), ownsData(true) {
        size_t idx = 0;
        for (T value : values) {
            if (idx < ni) {
                data[idx++] = value;
            }
        }
    }

    // Destructor to free memory
    ~FArray1D() {
        if (data != nullptr && ownsData) {
            delete[] data;
        }
    }

    // Access operator
    T& operator()(size_t i) {
        return data[i-start_i];
    }

    // Const access operator
    const T& operator()(size_t i) const {
        return data[i-start_i];
    }

    // Method to attach an existing Fortran array
    void attach(T* fortranArray) {
        data = fortranArray;
        ownsData = false;
    }

    void fill(const T& value) {
        for (size_t i=start_i; i <ni+start_i; i++) {
            *this(i) = value;
        }
    }

};


template <typename T>
class FArray2D {

  private:
    bool ownsData;
    int start_i, start_j;

  public:
    size_t ni, nj;
    T* data;

    // Constructor to allocate memory
    FArray2D(size_t ni, size_t nj, int start_i=1, int start_j=1)
        : ni(ni), nj(nj), start_i(start_i), start_j(start_j), data(new T[ni * nj]), ownsData(true) {}

    // Constructor to use existing Fortran array
    FArray2D(T* fortranArray, size_t ni, size_t nj, int start_i=1, int start_j=1)
        : ni(ni), nj(nj), start_i(start_i), start_j(start_j), data(fortranArray), ownsData(false) {}

    // Destructor to free memory
    ~FArray2D() {
        if (data != nullptr && ownsData) {
            delete[] data;
        }
    }

    // Access operator
    T& operator()(size_t i, size_t j) {
        return data[i-start_i + ni*(j-start_j)];
    }

    // Const access operator
    const T& operator()(size_t i, size_t j) const {
        return data[i-start_i + ni*(j-start_j)];
    }

    // Method to attach an existing Fortran array
    void attach(T* fortranArray) {
        data = fortranArray;
        ownsData = false;
    }

    void fill(const T& value) {
        for (size_t j=start_j; j<nj+start_j; j++) {
            for (size_t i=start_i; i<ni+start_i; i++) {
                (*this)(i, j) = value;
            }
        }
    }
};

