#include <FFMPcc.hpp>
#include <cmath>
#include <complex>
#include <FArray.hpp>
#include <Need.hpp>
#include <W1jet.hpp>
#include <mxpart_mod.hpp>
#include <sprods_com_mod.hpp>

using namespace mxpart_mod;
using namespace sprods_com_mod;

// Z. Bern, L. Dixon, D.A. Kosower, e-Print:hep-ph/9708239
// Eq10.10

static std::complex<double> FFMPcc_unsym(int j1, int j2, int j3, int j4, int j5, int j6,
                                          FArray2D<std::complex<double>>& za, FArray2D<std::complex<double>>& zb);
static std::complex<double> FFMPcc1(int j1, int j2, int j3, int j4, int j5, int j6,
                                     FArray2D<std::complex<double>>& za, FArray2D<std::complex<double>>& zb);
static std::complex<double> FFMPcc2(int j1, int j2, int j3, int j4, int j5, int j6,
                                     FArray2D<std::complex<double>>& za, FArray2D<std::complex<double>>& zb);

std::complex<double> FFMPcc(int j1, int j2, int j3, int j4, int j5, int j6,
                             FArray2D<std::complex<double>>& za, FArray2D<std::complex<double>>& zb) {
  std::complex<double> FFMPcc_res =
      FFMPcc_unsym(j1, j2, j3, j4, j5, j6, za, zb)
    + FFMPcc_unsym(j2, j1, j4, j3, j6, j5, zb, za);

  FFMPcc_res = FFMPcc_res; // @coverage-probe
  return FFMPcc_res;
}

// Z. Bern, L. Dixon, D.A. Kosower, e-Print:hep-ph/9708239
// Eq10.10
static std::complex<double> FFMPcc_unsym(int j1, int j2, int j3, int j4, int j5, int j6,
                                          FArray2D<std::complex<double>>& za, FArray2D<std::complex<double>>& zb) {
  auto zab2 = [&](int i1, int i2, int i3, int i4) {
    return za(i1, i2) * zb(i2, i4) + za(i1, i3) * zb(i3, i4);
  };
  auto zba2 = [&](int i1, int i2, int i3, int i4) {
    return zb(i1, i2) * za(i2, i4) + zb(i1, i3) * za(i3, i4);
  };
  auto zab = [&](int i1, int i2, int i3) {
    return za(i1, i2) * zb(i2, i3);
  };
  auto za22a = [&](int i1, int i2, int i3, int i4, int i5, int i6) {
    return zab2(i1, i2, i3, i4) * za(i4, i6)
         + zab2(i1, i2, i3, i5) * za(i5, i6);
  };
  auto zb21b = [&](int i1, int i2, int i3, int i4, int i5) {
    return zba2(i1, i2, i3, i4) * zb(i4, i5);
  };
  auto za21a = [&](int i1, int i2, int i3, int i4, int i5) {
    return zab2(i1, i2, i3, i4) * za(i4, i5);
  };

  double delta12 = s(j1, j2) - s(j3, j4) - s(j5, j6);

  std::complex<double> FFMPcc_unsym_res =
      std::pow(zab2(j5, j2, j3, j1), 2)
      / (zb(j2, j3) * za(j5, j6) * zab2(j4, j1, j2, j3) * zab2(j4, j2, j3, j1))
      * (Lsm1_2mht(s(j1, j4), t(j1, j2, j3), s(j2, j3), s(j5, j6))
         + Lsm1(-s(j1, j2), -t(j1, j2, j3), -s(j2, j3), -t(j1, j2, j3)))

    + (std::pow(zb(j2, j4), 3) * std::pow(za(j1, j5), 2) * t(j2, j3, j4)
       / (zb(j2, j3) * zb(j3, j4) * za(j5, j6) * std::pow(zab2(j1, j3, j4, j2), 3))
       - zb(j2, j4) * std::pow(zab2(j1, j2, j3, j4) * zab2(j5, j3, j4, j2), 2)
         / (zb(j2, j3) * zb(j3, j4) * za(j5, j6) * t(j2, j3, j4) * std::pow(zab2(j1, j3, j4, j2), 3))

       - std::pow(za(j2, j3) * zb(j1, j6), 2) * zab2(j3, j2, j4, j1)
         / (za(j3, j4) * zb(j5, j6) * t(j2, j3, j4)
            * zab2(j2, j3, j4, j1) * zab2(j4, j2, j3, j1)))
      * Lsm1_2mh(s(j1, j2), t(j2, j3, j4), s(j3, j4), s(j5, j6))

    + (std::pow(zb(j1, j3) * za(j4, j5) * t(j1, j2, j3), 2)
       / (zb(j2, j3) * za(j5, j6) * std::pow(zab2(j4, j1, j2, j3), 3) * zab2(j4, j2, j3, j1))
       - zab2(j4, j2, j3, j1) * std::pow(zab2(j5, j1, j2, j3), 2)
         / (zb(j2, j3) * za(j5, j6) * std::pow(zab2(j4, j1, j2, j3), 3)))
      * Lsm1_2mh(s(j3, j4), t(j1, j2, j3), s(j1, j2), s(j5, j6))

    - std::pow(za(j2, j3) * zb(j1, j6), 2)
      / (zb(j5, j6) * t(j2, j3, j4) * za(j2, j4) * zab2(j4, j2, j3, j1))
      * Lsm1(-s(j2, j3), -t(j2, j3, j4), -s(j3, j4), -t(j2, j3, j4))

    - 0.5 * zb(j1, j4) * (std::pow(za22a(j2, j1, j4, j2, j3, j5), 2)
                          - std::pow(za(j2, j5), 2) * s(j1, j4) * s(j2, j3))
      / (za(j1, j4) * zb(j2, j3) * za(j5, j6)
         * zab2(j2, j1, j4, j3) * zab2(j2, j3, j4, j1))
      * i3m(s(j1, j4), s(j2, j3), s(j5, j6))

    + (0.5 * zb(j2, j4) * std::pow(zab2(j5, j2, j3, j4), 2)
       * (2.0 * s(j3, j4) * s(j5, j6) + delta12 * t(j2, j3, j4))
       / (zb(j2, j3) * zb(j3, j4) * za(j5, j6) * std::pow(t(j2, j3, j4), 2) * zab2(j1, j3, j4, j2))

       + za(j2, j3) * zb(j1, j6) * zab2(j3, j2, j4, j1) * zab2(j5, j2, j3, j4)
         / (std::pow(t(j2, j3, j4), 2) * zab2(j4, j2, j3, j1))

       + 0.5 * za(j2, j3) * zb(j1, j6) * zab2(j3, j1, j4, j6) * zab2(j3, j2, j4, j1)
         / (za(j3, j4) * zb(j5, j6) * t(j2, j3, j4) * zab2(j4, j2, j3, j1))
       + 0.5 * zb(j1, j4) * za(j2, j5) * zb(j1, j6) * zab(j3, j2, j4)
         / (zb(j3, j4) * t(j2, j3, j4) * zab2(j4, j2, j3, j1))
       + 2.0 * za(j2, j3) * std::pow(zb(j2, j4), 2) * zab(j5, j1, j6)
         / (zb(j2, j3) * t(j2, j3, j4) * zab2(j1, j3, j4, j2))

       - zab(j3, j2, j1) * zab2(j5, j2, j3, j1) * zb(j4, j6)
         / (zb(j2, j3) * t(j1, j2, j3) * zab2(j4, j2, j3, j1))

       + 0.5 / (zab2(j1, j3, j4, j2) * zab2(j4, j2, j3, j1))

         * (zb(j1, j4) * zab(j3, j1, j6) * zab(j5, j2, j4) / zb(j3, j4)
            + zb(j1, j4) * zab(j5, j4, j2) * zab2(j5, j2, j3, j4) * delta12
              / (zb(j2, j3) * zb(j3, j4) * za(j5, j6))

            - za(j2, j3) * zb(j1, j6) / (za(j3, j4) * zb(j5, j6))
              * (zab(j3, j2, j6) * zab2(j3, j1, j4, j2) + zab(j3, j1, j2) * zab(j3, j5, j6))

            + 2.0 * zb(j1, j2) * zab(j3, j5, j6) * zab2(j5, j2, j3, j4) / zb(j2, j3)

            + zb(j2, j4) * zb(j1, j6) / (zb(j2, j3) * zb(j3, j4))
              * (zab(j5, j2, j4) * (s(j5, j6) - t(j1, j2, j3))
                 + zab(j5, j3, j4) * (s(j5, j6) + t(j2, j3, j4)))

            + zb(j1, j4) * za(j3, j5) * (2.0 * zab(j3, j4, j6) + zab(j3, j2, j6)))

       + 0.5 / (zab2(j1, j3, j4, j2) * zab2(j4, j1, j2, j3) * zab2(j4, j2, j3, j1))
         * (za(j4, j1) * zb(j1, j2) * za(j2, j3) * zb(j3, j4) / zb(j2, j3)
            * ((zab(j5, j1, j2) - zab(j5, j4, j2)) * zb(j1, j6)
               - 2.0 * zb(j1, j2) * zab(j5, j4, j6))

            + zb21b(j1, j3, j4, j2, j4)
              * (za(j3, j5) * zab(j4, j1, j6) + za(j4, j5) * zab(j3, j2, j6))
            + zab(j5, j3, j6) * (zab(j3, j2, j1) * s(j1, j3) + zab(j3, j4, j1) * s(j1, j2))

            + zb(j1, j3) * (zab(j3, j1, j6) - zab(j3, j2, j6)) * za21a(j3, j1, j2, j4, j5)
            + zab2(j5, j3, j4, j1) * zab(j3, j4, j6) * s(j2, j3)
            + zab(j5, j4, j1) * zab2(j3, j1, j2, j6) * s(j1, j3)

            + (3.0 * zab(j3, j2, j1) + zab(j3, j4, j1)) * zab(j5, j2, j6) * s(j1, j4)
            - zab(j5, j3, j1) * zab2(j1, j3, j4, j6) * (zab(j3, j2, j1) - zab(j3, j4, j1))

            + 2.0 * zab(j3, j4, j1) * zb(j1, j6)
              * (za(j5, j1) * (s(j1, j2) + t(j1, j2, j3)) - zab(j5, j2, j3) * za(j3, j1))
            - zab(j3, j2, j1) * zab(j5, j4, j6) * s(j3, j4)

            + 4.0 * za(j5, j1) * zb(j1, j2) * za(j2, j3) * zb(j3, j1) * zab(j3, j4, j6)

            - za(j2, j3) * zab2(j4, j2, j3, j1)
              * (2.0 * (zab(j5, j2, j4) - zab(j5, j3, j4)) * zb(j2, j6)
                 - zab(j5, j1, j6) * zb(j2, j4))))
      * i3m(s(j1, j2), s(j3, j4), s(j5, j6))

    + FFMPcc1(j1, j2, j3, j4, j5, j6, za, zb)
      * L0(-t(j2, j3, j4), -s(j3, j4)) / s(j3, j4)
    + FFMPcc2(j1, j2, j3, j4, j5, j6, za, zb)
      * L0(-t(j2, j3, j4), -s(j5, j6)) / s(j5, j6);

  return FFMPcc_unsym_res;
}

static std::complex<double> FFMPcc1(int j1, int j2, int j3, int j4, int j5, int j6,
                                     FArray2D<std::complex<double>>& za, FArray2D<std::complex<double>>& zb) {
  auto zab2 = [&](int i1, int i2, int i3, int i4) {
    return za(i1, i2) * zb(i2, i4) + za(i1, i3) * zb(i3, i4);
  };

  std::complex<double> FFMPcc1_res =
      2.0 * za(j2, j3) * zb(j2, j4) * zab2(j5, j2, j3, j4) * zab2(j5, j3, j4, j2)
      / (zb(j2, j3) * za(j5, j6) * t(j2, j3, j4) * zab2(j1, j3, j4, j2));

  return FFMPcc1_res;
}

static std::complex<double> FFMPcc2(int j1, int j2, int j3, int j4, int j5, int j6,
                                     FArray2D<std::complex<double>>& za, FArray2D<std::complex<double>>& zb) {
  auto zab2 = [&](int i1, int i2, int i3, int i4) {
    return za(i1, i2) * zb(i2, i4) + za(i1, i3) * zb(i3, i4);
  };

  std::complex<double> FFMPcc2_res =
      -2.0 * zb(j1, j4) * zb(j2, j4) * za(j1, j5) * zab2(j5, j2, j3, j4)
      / (zb(j2, j3) * zb(j3, j4) * za(j5, j6) * zab2(j1, j3, j4, j2));

  return FFMPcc2_res;
}

extern "C" {
  std::complex<double> FFMPcc_wrapper(int j1, int j2, int j3, int j4, int j5, int j6,
                                       std::complex<double>* fza, std::complex<double>* fzb) {
    FArray2D<std::complex<double>> za(fza, mxpart, mxpart);
    FArray2D<std::complex<double>> zb(fzb, mxpart, mxpart);
    return FFMPcc(j1, j2, j3, j4, j5, j6, za, zb);
  }
}
